python3 -c "
import os, csv, json, glob

# Find candidate source files (any csv or json in /workspace, excluding output)
candidates = [f for f in glob.glob('/workspace/*.csv') + glob.glob('/workspace/*.json') if 'totals.csv' not in f]

if not candidates:
    raise FileNotFoundError('No source data file found')

source = candidates[0]
totals = {}

if source.endswith('.json'):
    with open(source) as f:
        data = json.load(f)
    if isinstance(data, dict):
        # might be {category: [items]} or {items: [...]}
        for key, val in data.items():
            if isinstance(val, list):
                for row in val:
                    if 'category' in row and 'amount_usd' in row:
                        cat = row['category']
                        totals[cat] = totals.get(cat, 0) + float(row['amount_usd'])
        if not totals:
            # flat dict: {category: amount_usd, ...}
            for k, v in data.items():
                if isinstance(v, (int, float)):
                    totals[k] = float(v)
    elif isinstance(data, list):
        for row in data:
            if 'category' in row and 'amount_usd' in row:
                cat = row['category']
                totals[cat] = totals.get(cat, 0) + float(row['amount_usd'])
else:
    with open(source) as f:
        reader = csv.DictReader(f)
        for row in reader:
            cat = row['category']
            totals[cat] = totals.get(cat, 0) + float(row['amount_usd'])

# Sort descending by total
sorted_items = sorted(totals.items(), key=lambda x: x[1], reverse=True)

with open('/workspace/totals.csv', 'w', newline='') as f:
    f.write('category,total_usd\n')
    for cat, total in sorted_items:
        f.write(f'{cat},{total:.2f}\n')
"
