cd /workspace && python3 -c "
import csv, json, os, glob
from collections import defaultdict

data_files = [f for f in glob.glob('/workspace/*.csv') + glob.glob('/workspace/*.json') + glob.glob('/workspace/*.jsonl') if 'totals.csv' not in f]
records = []

for f in sorted(data_files):
    if f.endswith('.csv'):
        with open(f, newline='') as fh:
            reader = csv.DictReader(fh)
            rows = list(reader)
            if rows and 'category' in rows[0] and 'amount_usd' in rows[0]:
                records.extend(rows)
    elif f.endswith('.json'):
        with open(f) as fh:
            data = json.load(fh)
            if isinstance(data, list):
                for row in data:
                    if 'category' in row and 'amount_usd' in row:
                        records.append(row)
            elif isinstance(data, dict):
                for key in ('data','records','items','results','transactions'):
                    if key in data and isinstance(data[key], list):
                        for row in data[key]:
                            if 'category' in row and 'amount_usd' in row:
                                records.append(row)
    elif f.endswith('.jsonl'):
        with open(f) as fh:
            for line in fh:
                line = line.strip()
                if line:
                    row = json.loads(line)
                    if 'category' in row and 'amount_usd' in row:
                        records.append(row)

totals = defaultdict(float)
for r in records:
    totals[r['category']] += float(r['amount_usd'])

sorted_totals = sorted(totals.items(), key=lambda x: -x[1])

with open('/workspace/totals.csv', 'w', newline='') as out:
    w = csv.writer(out)
    w.writerow(['category', 'total_usd'])
    for cat, total in sorted_totals:
        w.writerow([cat, round(total, 2)])
"
