function human(bytes,    divisor, scaled, c) {
    if (bytes < 1024) return sprintf("%d", bytes)
    divisor = 1024
    scaled = int((bytes * 10 + divisor / 2) / divisor)
    c = "K"
    if (scaled >= 1024) { divisor = 1048576; scaled = int((bytes * 10 + divisor / 2) / divisor); c = "M" }
    if (scaled >= 1024) { divisor = 1073741824; scaled = int((bytes * 10 + divisor / 2) / divisor); c = "G" }
    if (scaled >= 1024) { divisor = 1099511627776; scaled = int((bytes * 10 + divisor / 2) / divisor); c = "T" }
    if (scaled % 10 == 0)
        return sprintf("%d%s", scaled / 10, c)
    else
        return sprintf("%d.%d%s", scaled / 10, scaled % 10, c)
}
{ printf "%s\t%s\n", human($1), $2 }
' > /workspace/top10.txt
